<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useWorkforce} from '../context'
import {useWorkforceText} from '../text'
import {useI18n} from 'vue-i18n'
import {employeeLoginText,type EmployeeLoginAccount} from '../employeeLogin'
import EmployeePasswordInput from './EmployeePasswordInput.vue'
const props=defineProps<{employeeId:string}>(),{api,current}=useWorkforce(),{t,error}=useWorkforceText()
const account=ref<EmployeeLoginAccount|null>(null),password=ref(''),loading=ref(true),busy=ref(false),failure=ref(''),notice=ref('')
const x=(key:Parameters<typeof employeeLoginText>[0])=>employeeLoginText(key,english()),path=()=>'/employees/'+props.employeeId+'/login-account'
async function refresh(){if(busy.value)return;loading.value=true;failure.value='';try{const value=await api().get<EmployeeLoginAccount|null>(path());if(current()){account.value=value;password.value=''}}catch(e){if(current())failure.value=error(e)}finally{if(current())loading.value=false}}
async function save(){if(busy.value||!account.value?.canReset||!password.value)return;if(!/^[A-Za-z0-9]{6}$/.test(password.value)){failure.value=t('invalid');return}busy.value=true;failure.value='';notice.value='';try{const result=await api().put<EmployeeLoginAccount>(path(),{expectedVersion:account.value.version,password:password.value});if(current()){account.value=result;password.value='';notice.value=x('saved')}}catch(e){if(current())failure.value=error(e)}finally{if(current())busy.value=false}}
async function useEmployeeNumber(){if(busy.value||!account.value?.canUseEmployeeNumber)return;busy.value=true;failure.value='';notice.value='';try{const result=await api().put<EmployeeLoginAccount>(path()+'/employee-number',{expectedVersion:account.value.version});if(current()){account.value=result;password.value='';notice.value=x('numberSaved')}}catch(e){if(current())failure.value=error(e)}finally{if(current())busy.value=false}}
async function changeStatus(){if(busy.value||!account.value?.canChangeStatus)return;const status=account.value.status==='active'?'disabled':'active';busy.value=true;failure.value='';notice.value='';try{const result=await api().put<EmployeeLoginAccount>(path()+'/status',{expectedVersion:account.value.version,status});if(current()){account.value=result;notice.value=x(status==='active'?'statusEnabled':'statusDisabled')}}catch(e){if(current())failure.value=error(e)}finally{if(current())busy.value=false}}
onMounted(refresh)
const {locale}=useI18n(),english=()=>locale.value.startsWith('en')
</script>
<template><section class="wf-panel wf-form-panel"><header class="wf-toolbar"><h2>{{x('title')}}</h2><button type="button" :disabled="loading||busy" @click="refresh">{{x('refresh')}}</button></header><p v-if="loading" role="status">{{x('loading')}}</p><p v-if="failure" role="alert" class="wf-error">{{failure}}</p><p v-if="notice" role="status">{{notice}}</p><template v-if="account&&!loading"><dl class="wf-details"><template v-if="account.employeeNo"><dt>{{x('employeeNo')}}</dt><dd>{{account.employeeNo}}</dd></template><dt>{{t('username')}}</dt><dd>{{account.username}}</dd><dt>{{t('status')}}</dt><dd>{{x(account.status==='active'?'enabled':'disabled')}}</dd><dt>{{x('product')}}</dt><dd>{{x(account.workforceAccess?'granted':'missing')}}</dd></dl><p class="wf-hint">{{x('statusSeparate')}}</p><button v-if="account.canChangeStatus" type="button" :disabled="busy" @click="changeStatus">{{x(account.status==='active'?'disableAccount':'enableAccount')}}</button><p v-else class="wf-hint">{{x('statusRestricted')}}</p><p v-if="account.status!=='active'" class="wf-hint">{{x('disabledHint')}}</p><button v-if="account.canUseEmployeeNumber&&account.username!==account.employeeNo" type="button" :disabled="busy" @click="useEmployeeNumber">{{x('useNumber')}}</button><p v-else-if="account.employeeNo&&account.username!==account.employeeNo" class="wf-hint">{{x('sharedNumber')}}</p><p class="wf-hint">{{x('loginHint')}}</p><form v-if="account.canReset" @submit.prevent="save"><EmployeePasswordInput v-model="password" :label="x('newPassword')" :disabled="busy"/><p class="wf-hint">{{x('hint')}}</p><p class="wf-hint">{{x('shared')}}</p><footer class="wf-form-actions"><button class="primary" :disabled="busy||!password">{{busy?t('saving'):x('save')}}</button></footer></form><p v-else class="wf-hint">{{x('readonly')}}</p></template><p v-else-if="!loading&&!failure">{{x('none')}}</p></section></template>
